<style>
.history-card{background:var(--mp-surface,#fff);color:var(--mp-ink,#182b37);border:1px solid var(--mp-border,#dae2e8);border-radius:12px;padding:18px;margin:14px 0;overflow-wrap:anywhere}.history-card h2,.history-card h3{margin:0 0 10px}.history-note{background:#f0f6ff;border-left:3px solid #2563eb;padding:12px;margin:12px 0;color:#294368;font-size:13px}.history-review{color:#8a4b08;background:#fff7e5;padding:10px;margin:10px 0;font-size:13px}.history-actions{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.history-actions a,.history-actions button{display:inline-block;padding:9px 12px;border:1px solid #c9d7e2;border-radius:8px;text-decoration:none;color:#155b89;background:white;font:inherit;cursor:pointer}.history-table-wrap{overflow-x:auto}.history-table{width:100%;border-collapse:collapse;font-size:13px}.history-table th,.history-table td{padding:10px 8px;border-bottom:1px solid #e1e8ed;text-align:left;vertical-align:top}.history-table th{white-space:nowrap}.history-table .amount{text-align:right;white-space:nowrap}.history-lines{font-size:12px;margin:8px 0;padding-left:18px}.history-row-meta{font-size:12px;line-height:1.6;color:#536372;white-space:normal;overflow-wrap:anywhere}.history-totals{margin:16px 0 0 auto;max-width:360px}.history-totals div{display:flex;justify-content:space-between;gap:20px;padding:5px 0}.history-source{font-size:12px;color:#627482}@media print{.history-actions,.no-print{display:none!important}.history-card{border:0;padding:0;break-inside:auto}.history-table-wrap{overflow:visible}.history-note{background:white;color:black}details{display:block}details>ul{display:block}}
</style>
